import cadquery as cq

plate = cq.Solid.makeBox(80, 50, 2, cq.Vector(-40, -25, 0))

centers_x = [-28, -20, -12, -4, 4, 12, 20, 28]
centers_y = [-16, -8, 0, 8, 16]

vent_solid = None
for cx in centers_x:
    for cy in centers_y:
        v = cq.Solid.makeBox(4, 4, 4, cq.Vector(cx - 2, cy - 2, -1))
        if vent_solid is None:
            vent_solid = v
        else:
            vent_solid = vent_solid.fuse(v)

plate = plate.cut(vent_solid)

hole_positions = [(36, 21), (36, -21), (-36, 21), (-36, -21)]
hole_solid = None
for x, y in hole_positions:
    h = cq.Solid.makeCylinder(1.5, 4, cq.Vector(x, y, -1), cq.Vector(0, 0, 1))
    if hole_solid is None:
        hole_solid = h
    else:
        hole_solid = hole_solid.fuse(h)

plate = plate.cut(hole_solid)

result = plate

